public interface IAgentSupervisor {
  AgentHandle RegisterAgent(IAgentLoop loop, string displayName, string kind);
  Task StopAgentAsync(string agentId);
  ObservableCollection<AgentRunDescriptor> RunningAgents { get; }
  ApprovalQueue Approvals { get; }
  IAuditLog AuditLog { get; }
}

public sealed class AgentSupervisor : IAgentSupervisor {
  private readonly ConcurrentDictionary<string, AgentRuntime> _agents = new();
  private readonly WorkspaceLockTable _locks;
  private readonly AgentMessageBus _bus;
  public AgentSupervisor(TerminalService terminal, GitService git, ChatService chat, IAuditLog auditLog, string workspaceRoot);
  public AgentHandle RegisterAgent(IAgentLoop loop, string displayName, string kind) {
    var ctx = new AgentContext(loop.AgentId, this, _terminal, _git, _chat, _workspaceRoot);
    var cts = new CancellationTokenSource();
    var runtime = new AgentRuntime(loop, ctx, cts);
    _agents[loop.AgentId] = runtime;
    _bus.Register(loop.AgentId);
    runtime.RunTask = Task.Run(() => RunGuardedAsync(runtime), cts.Token);
    return new AgentHandle(loop.AgentId, this);
  }
}

public interface IAgentContext {
  string AgentId { get; }
  string WorkspaceRoot { get; }
  Task<string> ReadFileAsync(string relativePath, CancellationToken ct);
  Task<bool> WriteFileAsync(string relativePath, string newContent, string rationale, CancellationToken ct);
  Task<bool> DeleteFileAsync(string relativePath, string rationale, CancellationToken ct);
  Task<TerminalCommandResult?> RunTerminalAsync(string command, string rationale, CancellationToken ct);
  Task<GitOperationResult?> RunGitAsync(Func<GitService, Task<GitOperationResult>> op, string rationale, CancellationToken ct);
  Task PostMessageAsync(string? toAgentId, string text, AgentMessageKind kind, CancellationToken ct);
  IAsyncEnumerable<AgentMessage> Inbox(CancellationToken ct);
  Task<string> AskAsync(string prompt, CancellationToken ct);
}

internal sealed class AgentContext : IAgentContext {
  public async Task<bool> WriteFileAsync(string relativePath, string newContent, string rationale, CancellationToken ct) {
    var fullPath = ResolveAndConfineOrThrow(relativePath);
    await using var claim = await _supervisor.ClaimAsync(AgentId, relativePath, ct);
    var oldContent = File.Exists(fullPath) ? await File.ReadAllTextAsync(fullPath, ct) : string.Empty;
    var request = AgentActionRequest.ForFileWrite(AgentId, relativePath, rationale, DiffBuilder.Unified(oldContent, newContent));
    var decision = await _supervisor.RequestApprovalAsync(request, ct);
    if (decision != ActionDecision.Approved) return false;
    await File.WriteAllTextAsync(fullPath, newContent, ct);
    return true;
  }
}

private string ResolveAndConfineOrThrow(string relativePath) {
  var full = Path.GetFullPath(Path.Combine(WorkspaceRoot, relativePath));
  if (!full.StartsWith(Path.GetFullPath(WorkspaceRoot) + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase))
    throw new SecurityException($"Path escapes workspace: {relativePath}");
  return full;
}

public sealed class PendingApproval : INotifyPropertyChanged {
  public AgentActionRequest Request { get; }
  internal TaskCompletionSource<ActionDecision> Tcs { get; }
}

public sealed class ApprovalQueue {
  public ObservableCollection<PendingApproval> Pending { get; } = new();
  public Task<ActionDecision> EnqueueAsync(AgentActionRequest request, TimeSpan timeout, CancellationToken ct);
  public void Resolve(Guid requestId, ActionDecision decision); // called from Approve/Deny buttons in the view
}

internal sealed class WorkspaceLockTable {
  private readonly ConcurrentDictionary<string, (string OwnerId, DateTimeOffset SinceUtc)> _owner = new(StringComparer.OrdinalIgnoreCase);
  public async Task<IWorkspaceClaim> ClaimAsync(string agentId, string path, AgentMessageBus bus, CancellationToken ct) {
    if (_owner.TryAdd(path, (agentId, DateTimeOffset.UtcNow))) return new WorkspaceClaim(path, agentId, this);
    var (ownerId, since) = _owner[path];
    if (ownerId == agentId) return new WorkspaceClaim(path, agentId, this); // reentrant
    await bus.PublishAsync(AgentMessage.ClaimRequest(agentId, ownerId, path, since), ct);
    throw new WorkspaceClaimConflictException(path, ownerId, since);
  }
}

internal sealed class AgentMessageBus {
  private readonly ConcurrentDictionary<string, Channel<AgentMessage>> _inboxes = new();
  public event EventHandler<AgentMessage>? MessagePosted;
  public void Register(string agentId);
  public void Unregister(string agentId);
  public async Task PublishAsync(AgentMessage message, CancellationToken ct);
  public IAsyncEnumerable<AgentMessage> ReadInbox(string agentId, CancellationToken ct);
}

